import hashlib
import os
import secrets
import sys
import warnings


DEFAULT_ITERATIONS = 600_000
MIN_ITERATIONS = 600_000
MAX_ITERATIONS = 2_147_483_647
SALT_LENGTH = 16
DERIVED_KEY_LENGTH = 32


class SafeArgumentParser(argparse.ArgumentParser):
    """Keep rejected command-line values out of diagnostics."""

    def error(self, message: str) -> None:
        del message
        self.print_usage(sys.stderr)
        self.exit(2, f"{self.prog}: error: invalid command line\n")


def parse_iterations(value: str) -> int:
    try:
        iterations = int(value, 10)
    except ValueError:
        raise argparse.ArgumentTypeError("must be a base-10 integer") from None

    if not MIN_ITERATIONS <= iterations <= MAX_ITERATIONS:
        raise argparse.ArgumentTypeError(
            f"must be between {MIN_ITERATIONS} and {MAX_ITERATIONS}"
        )
    return iterations


def build_parser() -> argparse.ArgumentParser:
    parser = SafeArgumentParser(
        description="Generate a PBKDF2-HMAC-SHA256 repository deletion password verifier."
    )
    parser.add_argument(
        "--iterations",
        type=parse_iterations,
        default=DEFAULT_ITERATIONS,
        metavar="COUNT",
        help=(
            f"PBKDF2 iteration count (default: {DEFAULT_ITERATIONS}; "
            f"minimum: {MIN_ITERATIONS}; maximum: {MAX_ITERATIONS})"
        ),
    )
    parser.add_argument(
        "--password-stdin",
        action="store_true",
        help="read the exact password bytes from standard input",
    )
    return parser


def read_stdin_password() -> str:
    try:
        password_bytes = sys.stdin.buffer.read()
    except (AttributeError, OSError, ValueError):
        raise ValueError("Could not read password bytes from standard input.") from None

    try:
        password = password_bytes.decode("utf-8", errors="strict")
    except UnicodeDecodeError:
        raise ValueError("Password input must be valid UTF-8.") from None

    if not password:
        raise ValueError("Password must not be empty.")
    return password


def require_usable_terminal() -> None:
    try:
        if os.name == "nt":
            if sys.stdin is None or not sys.stdin.isatty():
                raise OSError("standard input is not a terminal")
        else:
            with open("/dev/tty", "rb", buffering=0) as terminal:
                if not os.isatty(terminal.fileno()):
                    raise OSError("not a terminal")
    except (OSError, ValueError):
        raise ValueError(
            "Interactive password entry requires a usable terminal; use --password-stdin."
        ) from None


def read_interactive_password() -> str:
    require_usable_terminal()
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", getpass.GetPassWarning)
            password = getpass.getpass("Password: ", stream=sys.stderr)
            if not password:
                raise ValueError("Password must not be empty.")
            confirmation = getpass.getpass("Confirm password: ", stream=sys.stderr)
    except getpass.GetPassWarning:
        raise ValueError(
            "Password input could not be masked; use a terminal that supports hidden input."
        ) from None

    if password != confirmation:
        raise ValueError("Passwords do not match.")
    return password


def make_verifier(password: str, iterations: int) -> str:
    if not password:
        raise ValueError("Password must not be empty.")

    try:
        password_bytes = password.encode("utf-8", errors="strict")
    except UnicodeEncodeError:
        raise ValueError("Password must be representable as UTF-8.") from None

    salt = secrets.token_bytes(SALT_LENGTH)
    derived_key = hashlib.pbkdf2_hmac(
        "sha256", password_bytes, salt, iterations, dklen=DERIVED_KEY_LENGTH
    )
    salt_encoded = base64.b64encode(salt).decode("ascii")
    key_encoded = base64.b64encode(derived_key).decode("ascii")
    return f"{{pbkdf2-sha256}}{iterations}:{salt_encoded}:{key_encoded}"


